#!/usr/bin/env python3
"""Restore complete bounded plural teaching/remediation; preserve every scored/native field."""
import sys,json,hashlib
from pathlib import Path
from copy import deepcopy
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'catalog'))
from curriculum_storage import loads,dumps
PACK=ROOT/'app/src/main/assets/content/v2-curriculum.json';BASELINE='3812f0e793ac6478a809fe683b303048e6f1c69c';OBJ='obj-u8-plural';PREFIX='prov-ca-u8-plural-instruction-'
sha=lambda s:hashlib.sha256(s.encode()).hexdigest()
def main():
 raw=PACK.read_bytes();p=loads(raw)
 if any(r['itemId'].startswith(PREFIX) for r in p['provenanceRecords']):return
 basis=('Complete frozen OpenRussian nouns.csv commit50e210c4803237779cb562bc1abcea529066031c header and seven selected full rows, sg_nom/pl_nom/gender/English dictionary labels. Existing field-bound native records and apostrophe-to-combining-acute formatting unchanged. Existing CC BY-SA4.0 contributor/rights route retained. Wikibooks Adjectives4292379 complete nominative agreement/spelling context supplies plural adjective agreement regardless of noun gender. Broad all-ending/soft-adjective generalizations excluded. Independent English,2026-10-13; bounded recognition of seven supplied nominative pairs, not unrestricted formation/all cases/unseen or productive mastery. Dictionary English lemma labels are not plural sentence translations. No new Russian or private Penguin prose; qualified source/rights/semantic approval pending.')
 template=next(r for r in p['provenanceRecords'] if r['itemId']=='prov-ca-u5-behavior-teach-1-body');added=[]
 def record(text,name):
  r=deepcopy(template);original=basis+'\n'+text;r.update(itemId=PREFIX+name,unitNumber=8,objectiveId=OBJ,sourceRecordId='ca-coverage:'+OBJ+':instruction:'+name,originalSourceText=original,shippedText=text,sourceHash=sha(original),contentHash=sha(text));r['synthesis'].update(bibliography=basis,authorshipDeclaration='Independent English,2026-10-13; existing frozen native forms/labels retained, no generated native or private prose.',objectiveOrClaimBinding=OBJ+':instruction:'+name,applications=[]);p['provenanceRecords'].append(r);added.append(r['itemId'])
 u=p['units'][7];o=next(o for o in u['objectives'] if o['id']==OBJ);oldobj=deepcopy(o);o['title']='Recognize supplied singular and plural nominative noun forms';record(o['title'],'objective-title')
 s=next(s for s in u['sessions'] if s['id']=='u8-s-plural');oldsession=deepcopy(s);teach=[t for t in s['steps'] if t['kind']=='TEACH'];assert len(teach)==8
 cards=[('Distinguish one table from tables','сто́л is singular nominative; столы́ is plural nominative. In the selected table sense, the plural refers to tables. The English notes beside these examples are dictionary labels, not plural English translations or complete sentences. Choose the plural form when the question requests plural nominative. Both the ending and the supplied stress matter; do not insert a new stress pattern.'),
 ('Keep lexical gender separate from plural agreement','These checks select supplied nominative plural noun forms. Each noun retains its dictionary gender; plural adjective agreement does not require separate masculine, feminine and neuter plural endings. The source’s single plural agreement category is not a claim that nouns lose lexical gender. Gender alone is not a complete algorithm for unfamiliar plural endings or stress. Learn these supplied pairs rather than applying them to every noun.'),
 ('Recognize the town pair','го́род is singular nominative; города́ is plural nominative in this supplied pair. Select the latter for towns. The plural ending differs from the table pair and its supplied stress is on the final syllable. These patterns are word-specific recognition evidence, not permission to generate an unlisted form.'),
 ('Recognize the book pair and its spelling','кни́га is singular nominative; кни́ги is plural nominative. Select the latter for books. The supplied plural retains its stress. Its final vowel follows the stem’s last consonant, one of the seven spelling-rule letters taught in the later spelling session. This same correct book pair is reused there as reinforcement; earlier independent credit does not replace that later objective’s checks.'),
 ('Recognize the window pair and shifted stress','окно́ is singular nominative; о́кна is plural nominative in the supplied dictionary pair. Select the latter for windows. Notice the supplied stress moves to the first syllable. An ending-only guess would lose part of the taught form; do not invent another accent or treat this pair as every neuter noun’s algorithm.'),
 ('Recognize the mom pair','ма́ма is singular nominative; ма́мы is plural nominative. Select the latter for moms in the supplied sense. The ending changes while the supplied stress stays in place. A feminine dictionary label alone does not prove every feminine noun has this ending.'),
 ('Recognize the house pair','до́м is singular nominative; дома́ is plural nominative in the supplied house sense. Select the latter for houses. Preserve the source stress shift. The dictionary’s English house/home labels identify a sense; they are not a plural translation of the Russian form.'),
 ('Recognize the word pair within the taught scope','сло́во is singular nominative; слова́ is plural nominative in the supplied word sense. Select the latter for words. Preserve its final stress. The seven pairs in this lesson cover several endings and stress patterns, but do not establish an unrestricted productive plural algorithm or meanings in every case. A missed choice returns to all cards and fourteen original worked forms.')]
 for n,(t,(title,body)) in enumerate(zip(teach,cards)):t.update(title=title,body=body);record(title,str(n)+'-title');record(body,str(n)+'-body')
 s['steps']=teach+[t for t in s['steps'] if t['kind']!='TEACH']
 for t in s['steps']:
  if t['kind'] in ['GUIDED','CHECK']:t['body']='Choose the supplied nominative plural form. A missed answer returns to every teaching card and worked pair.';record(t['body'],t['id']+'-body')
  if t['kind']=='REMEDIATE':t.update(title='Review all seven supplied nominative pairs',body='\n\n'.join(t['body'] for t in teach),exampleIds=list(dict.fromkeys(e for t in teach for e in t.get('exampleIds',[]))));record(t['title'],'rem-title');record(t['body'],'rem-body')
 after=dumps(p).encode();PACK.write_bytes(after);(ROOT/'audit/content-corrections/UNIT8_PLURAL_INSTRUCTION_CORRECTION.json').write_text(json.dumps(dict(baselineCommit=BASELINE,beforeSha256=hashlib.sha256(raw).hexdigest(),afterSha256=hashlib.sha256(after).hexdigest(),changes=[dict(before=oldobj,after=deepcopy(o)),dict(before=oldsession,after=deepcopy(s))],addedProvenanceIds=added,bibliography=basis,allScoredItemsUnchanged=True,allNativeExamplesUnchanged=True,semanticAcceptance=False,unseenContextClaim=False,productivePluralClaim=False),ensure_ascii=False,indent=2)+'\n');print('Added',len(added),'pending English records; all scored/native fields unchanged')
if __name__=='__main__':main()
